"use client";

import { useEffect, useState } from "react";
import { getIdentities } from "@/lib/api/identities";

export default function IdentitiesPage() {
  const [identities, setIdentities] = useState([]);

  useEffect(() => {
    async function load() {
      const data = await getIdentities();
      setIdentities(data.data || []);
    }

    load();
  }, []);

  return (
    <div className="p-6 text-white">
      <h1 className="text-xl font-bold mb-4">Identities</h1>

      <div className="space-y-2">
        {identities.map((identity: any) => (
          <div
            key={identity.identityId}
            className="bg-[#222] p-3 rounded border border-[#333]"
          >
            <div>ID: {identity.identityId}</div>
            <div>Detections: {identity.detectionCount}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
